import pandapower as pp
from pandapower.contingency import run_contingency

# Load IEEE 30-bus case
net = pp.networks.case_ieee30()

# Run base power flow to identify the online generator with the highest active power dispatch
pp.runpp(net)

# Find online generators (in-service) and their active power dispatch
gen_mask = net.gen.in_service.values if len(net.gen) else []
if len(net.gen) > 0:
    online_gens = net.gen[net.gen.in_service].copy()
    if len(online_gens) > 0:
        max_gen_idx = online_gens["p_mw"].idxmax()
        # Reduce that unit to a lower dispatch level
        net.gen.at[max_gen_idx, "p_mw"] = net.gen.at[max_gen_idx, "p_mw"] * 0.5

# Re-run power flow after modification
pp.runpp(net)

# Prepare N-1 contingency cases for all lines
nminus1_cases = {"line": {"index": net.line.index.values}}

# Run contingency analysis
contingency_results = run_contingency(net, nminus1_cases, write_to_net=False)

# Extract maximum loading percentage across all line contingencies
max_loading = None

# Try common result structures returned by run_contingency
if isinstance(contingency_results, dict):
    # Look for line-related results
    for key in contingency_results.keys():
        val = contingency_results[key]
        if isinstance(val, dict):
            for subkey in val.keys():
                arr = val[subkey]
                try:
                    import numpy as np
                    arr = np.asarray(arr, dtype=float)
                    if arr.size > 0:
                        local_max = np.nanmax(arr)
                        if max_loading is None or local_max > max_loading:
                            max_loading = local_max
                except Exception:
                    pass
        else:
            try:
                import numpy as np
                arr = np.asarray(val, dtype=float)
                if arr.size > 0:
                    local_max = np.nanmax(arr)
                    if max_loading is None or local_max > max_loading:
                        max_loading = local_max
            except Exception:
                pass

# Fallback: inspect net.res_line if contingency wrote results there
if max_loading is None and hasattr(net, "res_line") and len(net.res_line) > 0:
    if "loading_percent" in net.res_line.columns:
        max_loading = float(net.res_line["loading_percent"].max())

print(float(max_loading) if max_loading is not None else float("nan"))

